#!/usr/bin/env python3
"""Fill a Word (.docx) template with values from a JSON file.

Usage:
    python3 /skills/docx/fill_template.py TEMPLATE.docx DATA.json OUTPUT.docx

Handles every case a hand-written loop misses (the usual cause of a 0 score):
  * placeholders split across XML runs  (e.g. "{{POSI" + "TION}}")
  * placeholders in tables AND nested tables (any depth)
  * placeholders in headers and footers
  * {{IF_NAME}}...{{END_IF_NAME}} conditional sections

The script rewrites every {{TOKEN}} whose KEY exists in the JSON, keeps the first
run's formatting, then self-verifies that no {{...}} placeholder remains and exits
non-zero (listing what is left) if any do.
"""
import json
import re
import sys

from docx import Document

PLACEHOLDER = re.compile(r"\{\{\s*([A-Za-z0-9_]+)\s*\}\}")
IF_OPEN = re.compile(r"\{\{\s*IF_([A-Za-z0-9_]+)\s*\}\}")
IF_CLOSE = re.compile(r"\{\{\s*END_IF_([A-Za-z0-9_]+)\s*\}\}")
FALSEY = {"", "no", "n", "false", "0", "none", "off", "false", "excluded"}


def _norm(s):
    return re.sub(r"[^a-z0-9]", "", str(s).lower())


def _flatten(obj, out):
    """Flatten nested dict/list JSON into {normalized_key: «redacted»
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                _flatten(v, out)
            else:
                out.setdefault(_norm(k), v)
    elif isinstance(obj, list):
        for v in obj:
            _flatten(v, out)
    return out


def _condition_is_true(name, data, flat):
    """Decide whether an {{IF_NAME}} block should be KEPT.

    Truthy if a matching flag value is truthy. Common patterns: a key equal to
    NAME, or NAME + a suffix such as _PACKAGE / _INCLUDED / _FLAG. If no flag is
    found we KEEP the content (only strip the markers) — safer than deleting text.
    """
    candidates = [name, name + "_PACKAGE", name + "_INCLUDED", name + "_FLAG",
                  name + "_ENABLED", "INCLUDE_" + name]
    for c in candidates:
        if _norm(c) in flat:
            v = flat[_norm(c)]
            if isinstance(v, bool):
                return v
            return str(v).strip().lower() not in FALSEY
    return True  # unknown flag -> keep content, just remove markers


def _resolve(text, data, flat):
    """Replace every {{KEY}} in text whose key is known."""
    def sub(m):
        key = «redacted»
        if key in data:
            return str(data[key])
        nk = _norm(key)
        if nk in flat:
            return str(flat[nk])
        return m.group(0)  # leave unknown tokens untouched
    return PLACEHOLDER.sub(sub, text)


def _set_paragraph_text(para, new_text):
    """Write new_text into the paragraph, preserving the first run's format."""
    if para.runs:
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ""
    else:
        para.text = new_text


def _process_paragraphs(paragraphs, data, flat):
    """Handle single-paragraph conditionals + placeholder substitution.

    Multi-paragraph conditionals (open marker and close marker in different
    paragraphs of the SAME list) are handled by _strip_spanning_conditionals.
    """
    for para in paragraphs:
        text = para.text
        if "{{" not in text:
            continue
        new_text = text
        # single-paragraph conditional: {{IF_X}} ... {{END_IF_X}} in one paragraph
        m_open = IF_OPEN.search(new_text)
        m_close = IF_CLOSE.search(new_text)
        if m_open and m_close and m_open.start() < m_close.start():
            name = m_open.group(1)
            if _condition_is_true(name, data, flat):
                new_text = IF_OPEN.sub("", new_text, count=1)
                new_text = IF_CLOSE.sub("", new_text, count=1)
            else:
                new_text = new_text[:m_open.start()] + new_text[m_close.end():]
        new_text = _resolve(new_text, data, flat)
        if new_text != text:
            _set_paragraph_text(para, new_text)


def _strip_spanning_conditionals(paragraphs, data, flat):
    """Handle {{IF_X}} and {{END_IF_X}} that live in different paragraphs."""
    i = 0
    n = len(paragraphs)
    while i < n:
        mo = IF_OPEN.search(paragraphs[i].text)
        if mo:
            name = mo.group(1)
            # find the closing paragraph
            j = i
            while j < n and not IF_CLOSE.search(paragraphs[j].text):
                j += 1
            if j < n:
                keep = _condition_is_true(name, data, flat)
                for k in range(i, j + 1):
                    t = paragraphs[k].text
                    t = IF_OPEN.sub("", t)
                    t = IF_CLOSE.sub("", t)
                    if not keep:
                        t = ""
                    t = _resolve(t, data, flat)
                    _set_paragraph_text(paragraphs[k], t)
                i = j + 1
                continue
        i += 1


def _process_table(table, data, flat):
    for row in table.rows:
        for cell in row.cells:
            _strip_spanning_conditionals(cell.paragraphs, data, flat)
            _process_paragraphs(cell.paragraphs, data, flat)
            for nested in cell.tables:
                _process_table(nested, data, flat)


def fill(template_path, data_path, output_path):
    with open(data_path) as f:
        data = json.load(f)
    flat = _flatten(data, {})

    doc = Document(template_path)

    _strip_spanning_conditionals(doc.paragraphs, data, flat)
    _process_paragraphs(doc.paragraphs, data, flat)
    for table in doc.tables:
        _process_table(table, data, flat)
    for section in doc.sections:
        for hf in (section.header, section.footer,
                   section.first_page_header, section.first_page_footer,
                   section.even_page_header, section.even_page_footer):
            _strip_spanning_conditionals(hf.paragraphs, data, flat)
            _process_paragraphs(hf.paragraphs, data, flat)
            for table in hf.tables:
                _process_table(table, data, flat)

    doc.save(output_path)

    # ---- self-verify: no placeholder may remain anywhere ----
    check = Document(output_path)
    remaining = []

    def scan(paras):
        for p in paras:
            remaining.extend(PLACEHOLDER.findall(p.text))

    def scan_table(t):
        for row in t.rows:
            for cell in row.cells:
                scan(cell.paragraphs)
                for nt in cell.tables:
                    scan_table(nt)

    scan(check.paragraphs)
    for t in check.tables:
        scan_table(t)
    for s in check.sections:
        scan(s.header.paragraphs)
        scan(s.footer.paragraphs)

    if remaining:
        sys.stderr.write(
            "ERROR: %d placeholder(s) still unresolved: %s\n"
            "Add the missing key(s) to %s and re-run.\n"
            % (len(remaining), sorted(set(remaining)), data_path))
        sys.exit(1)
    print("OK: %s written, 0 remaining placeholders." % output_path)


def _discover(args):
    """Best-effort mapping of loose CLI args to (template, data, output).

    Rules: the .json arg is the data file; a .docx arg that already exists on
    disk is the template; the other .docx arg is the output. Missing pieces are
    searched for in the output dir, /root, and the current dir.
    """
    import glob
    import os

    docx_args = [a for a in args if a.lower().endswith(".docx")]
    json_args = [a for a in args if a.lower().endswith(".json")]

    data = json_args[0] if json_args else None
    template = next((a for a in docx_args if os.path.exists(a)), None)
    output = next((a for a in docx_args if a != template), None)

    search_dirs = []
    if output:
        search_dirs.append(os.path.dirname(os.path.abspath(output)) or ".")
    search_dirs += ["/root", os.getcwd()]

    if template is None:
        for d in search_dirs:
            cands = [p for p in glob.glob(os.path.join(d, "*.docx"))
                     if p != output and os.path.exists(p)]
            for p in cands:
                try:
                    if PLACEHOLDER.search(Document(p).paragraphs and "".join(
                            pp.text for pp in Document(p).paragraphs) or ""):
                        template = p
                        break
                except Exception:
                    continue
            if template is None and cands:
                template = cands[0]
            if template:
                break
    if data is None:
        for d in search_dirs:
            cands = glob.glob(os.path.join(d, "*.json"))
            if cands:
                data = cands[0]
                break
    return template, data, output


def main(argv):
    args = argv[1:]
    if len(args) == 3 and all(a for a in args):
        template, data, output = args
        import os
        if not os.path.exists(template):
            t2, d2, _ = _discover(args)
            template = t2 or template
            data = d2 or data
    else:
        template, data, output = _discover(args)

    if not (template and data and output):
        sys.stderr.write(
            "Usage: python3 fill_template.py TEMPLATE.docx DATA.json OUTPUT.docx\n"
            "(could not auto-discover the missing paths; pass all three)\n")
        sys.exit(2)
    fill(template, data, output)


if __name__ == "__main__":
    main(sys.argv)
